mkuse!{use std :: borrow :: Cow ;}
mkuse!{use std :: io ;}
mkuse!{use std :: io :: prelude :: * ;}
mkuse!{use LabelText :: * ;}
mkitem!{mkenum!{# [doc = " The text for a graphviz label on a node or edge."] pub enum LabelText < 'a > { # [doc = " This kind of label preserves the text directly as is."] # [doc = ""] # [doc = " Occurrences of backslashes (`\\`) are escaped, and thus appear"] # [doc = " as backslashes in the rendered label."] LabelStr (Cow < 'a , str >) , # [doc = " This kind of label uses the graphviz label escString type:"] # [doc = " <https://www.graphviz.org/docs/attr-types/escString>"] # [doc = ""] # [doc = " Occurrences of backslashes (`\\`) are not escaped; instead they"] # [doc = " are interpreted as initiating an escString escape sequence."] # [doc = ""] # [doc = " Escape sequences of particular interest: in addition to `\\n`"] # [doc = " to break a line (centering the line preceding the `\\n`), there"] # [doc = " are also the escape sequences `\\l` which left-justifies the"] # [doc = " preceding line and `\\r` which right-justifies it."] EscStr (Cow < 'a , str >) , # [doc = " This uses a graphviz [HTML string label][html]. The string is"] # [doc = " printed exactly as given, but between `<` and `>`. **No"] # [doc = " escaping is performed.**"] # [doc = ""] # [doc = " [html]: https://www.graphviz.org/doc/info/shapes.html#html"] HtmlStr (Cow < 'a , str >) , }}}
mkitem!{mkenum!{# [doc = " The style for a node or edge."] # [doc = " See <https://www.graphviz.org/docs/attr-types/style/> for descriptions."] # [doc = " Note that some of these are not valid for edges."] # [derive (Copy , Clone , PartialEq , Eq , Debug)] pub enum Style { None , Solid , Dashed , Dotted , Bold , Rounded , Diagonals , Filled , Striped , Wedged , }}}
mkitem!{mkimpl!{impl Style { pub fn as_slice (self) -> & 'static str { match self { Style :: None => "" , Style :: Solid => "solid" , Style :: Dashed => "dashed" , Style :: Dotted => "dotted" , Style :: Bold => "bold" , Style :: Rounded => "rounded" , Style :: Diagonals => "diagonals" , Style :: Filled => "filled" , Style :: Striped => "striped" , Style :: Wedged => "wedged" , } } }}}
mkitem!{mkstruct!{# [doc = " `Id` is a Graphviz `ID`."] pub struct Id < 'a > { name : Cow < 'a , str > , }}}
mkitem!{mkimpl!{impl < 'a > Id < 'a > { # [doc = " Creates an `Id` named `name`."] # [doc = ""] # [doc = " The caller must ensure that the input conforms to an"] # [doc = " identifier format: it must be a non-empty string made up of"] # [doc = " alphanumeric or underscore characters, not beginning with a"] # [doc = " digit (i.e., the regular expression `[a-zA-Z_][a-zA-Z_0-9]*`)."] # [doc = ""] # [doc = " (Note: this format is a strict subset of the `ID` format"] # [doc = " defined by the DOT language. This function may change in the"] # [doc = " future to accept a broader subset, or the entirety, of DOT's"] # [doc = " `ID` format.)"] # [doc = ""] # [doc = " Passing an invalid string (containing spaces, brackets,"] # [doc = " quotes, ...) will return an empty `Err` value."] pub fn new < Name : Into < Cow < 'a , str > > > (name : Name) -> Result < Id < 'a > , () > { let name = name . into () ; match name . chars () . next () { Some (c) if c . is_ascii_alphabetic () || c == '_' => { } _ => return Err (()) , } if ! name . chars () . all (| c | c . is_ascii_alphanumeric () || c == '_') { return Err (()) ; } Ok (Id { name }) } pub fn as_slice (& 'a self) -> & 'a str { & self . name } }}}
mkitem!{mktrait!{# [doc = " Each instance of a type that implements `Label<C>` maps to a"] # [doc = " unique identifier with respect to `C`, which is used to identify"] # [doc = " it in the generated .dot file. They can also provide more"] # [doc = " elaborate (and non-unique) label text that is used in the graphviz"] # [doc = " rendered output."] # [doc = " The graph instance is responsible for providing the DOT compatible"] # [doc = " identifiers for the nodes and (optionally) rendered labels for the nodes and"] # [doc = " edges, as well as an identifier for the graph itself."] pub trait Labeller < 'a > { type Node ; type Edge ; # [doc = " Must return a DOT compatible identifier naming the graph."] fn graph_id (& 'a self) -> Id < 'a > ; # [doc = " Maps `n` to a unique identifier with respect to `self`. The"] # [doc = " implementor is responsible for ensuring that the returned name"] # [doc = " is a valid DOT identifier."] fn node_id (& 'a self , n : & Self :: Node) -> Id < 'a > ; # [doc = " Maps `n` to one of the [graphviz `shape` names][1]. If `None`"] # [doc = " is returned, no `shape` attribute is specified."] # [doc = ""] # [doc = " [1]: https://www.graphviz.org/doc/info/shapes.html"] fn node_shape (& 'a self , _node : & Self :: Node) -> Option < LabelText < 'a > > { None } # [doc = " Maps `n` to a label that will be used in the rendered output."] # [doc = " The label need not be unique, and may be the empty string; the"] # [doc = " default is just the output from `node_id`."] fn node_label (& 'a self , n : & Self :: Node) -> LabelText < 'a > { LabelStr (self . node_id (n) . name) } # [doc = " Maps `e` to a label that will be used in the rendered output."] # [doc = " The label need not be unique, and may be the empty string; the"] # [doc = " default is in fact the empty string."] fn edge_label (& 'a self , _e : & Self :: Edge) -> LabelText < 'a > { LabelStr ("" . into ()) } # [doc = " Maps `n` to a style that will be used in the rendered output."] fn node_style (& 'a self , _n : & Self :: Node) -> Style { Style :: None } # [doc = " Maps `e` to a style that will be used in the rendered output."] fn edge_style (& 'a self , _e : & Self :: Edge) -> Style { Style :: None } }}}

macro_rules! escape_html_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function escape_html in module {}", module_path!());
    };
}

mkfn!{
    escape_html_introspect!();
    # [doc = " Escape tags in such a way that it is suitable for inclusion in a"] # [doc = " Graphviz HTML label."] pub fn escape_html (s : & str) -> String { s . replace ('&' , "&amp;") . replace ('\"' , "&quot;") . replace ('<' , "&lt;") . replace ('>' , "&gt;") . replace ('\n' , "<br align=\"left\"/>") }
}
mkitem!{mkimpl!{impl < 'a > LabelText < 'a > { pub fn label < S : Into < Cow < 'a , str > > > (s : S) -> LabelText < 'a > { LabelStr (s . into ()) } pub fn html < S : Into < Cow < 'a , str > > > (s : S) -> LabelText < 'a > { HtmlStr (s . into ()) } fn escape_char < F > (c : char , mut f : F) where F : FnMut (char) , { match c { '\\' => f (c) , _ => { for c in c . escape_default () { f (c) } } } } fn escape_str (s : & str) -> String { let mut out = String :: with_capacity (s . len ()) ; for c in s . chars () { LabelText :: escape_char (c , | c | out . push (c)) ; } out } # [doc = " Renders text as string suitable for a label in a .dot file."] # [doc = " This includes quotes or suitable delimiters."] pub fn to_dot_string (& self) -> String { match * self { LabelStr (ref s) => format ! ("\"{}\"" , s . escape_default ()) , EscStr (ref s) => format ! ("\"{}\"" , LabelText :: escape_str (s)) , HtmlStr (ref s) => format ! ("<{s}>") , } } }}}
mkitem!{pub type Nodes < 'a , N > = Cow < 'a , [N] > ;}
mkitem!{pub type Edges < 'a , E > = Cow < 'a , [E] > ;}
mkitem!{mktrait!{# [doc = " GraphWalk is an abstraction over a directed graph = (nodes,edges)"] # [doc = " made up of node handles `N` and edge handles `E`, where each `E`"] # [doc = " can be mapped to its source and target nodes."] # [doc = ""] # [doc = " The lifetime parameter `'a` is exposed in this trait (rather than"] # [doc = " introduced as a generic parameter on each method declaration) so"] # [doc = " that a client impl can choose `N` and `E` that have substructure"] # [doc = " that is bound by the self lifetime `'a`."] # [doc = ""] # [doc = " The `nodes` and `edges` method each return instantiations of"] # [doc = " `Cow<[T]>` to leave implementors the freedom to create"] # [doc = " entirely new vectors or to pass back slices into internally owned"] # [doc = " vectors."] pub trait GraphWalk < 'a > { type Node : Clone ; type Edge : Clone ; # [doc = " Returns all the nodes in this graph."] fn nodes (& 'a self) -> Nodes < 'a , Self :: Node > ; # [doc = " Returns all of the edges in this graph."] fn edges (& 'a self) -> Edges < 'a , Self :: Edge > ; # [doc = " The source node for `edge`."] fn source (& 'a self , edge : & Self :: Edge) -> Self :: Node ; # [doc = " The target node for `edge`."] fn target (& 'a self , edge : & Self :: Edge) -> Self :: Node ; }}}
mkitem!{mkenum!{# [derive (Clone , PartialEq , Eq , Debug)] pub enum RenderOption { NoEdgeLabels , NoNodeLabels , NoEdgeStyles , NoNodeStyles , Fontname (String) , DarkTheme , }}}

macro_rules! render_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function render in module {}", module_path!());
    };
}

mkfn!{
    render_introspect!();
    # [doc = " Renders directed graph `g` into the writer `w` in DOT syntax."] # [doc = " (Simple wrapper around `render_opts` that passes a default set of options.)"] pub fn render < 'a , N , E , G , W > (g : & 'a G , w : & mut W) -> io :: Result < () > where N : Clone + 'a , E : Clone + 'a , G : Labeller < 'a , Node = N , Edge = E > + GraphWalk < 'a , Node = N , Edge = E > , W : Write , { render_opts (g , w , & []) }
}

macro_rules! render_opts_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function render_opts in module {}", module_path!());
    };
}

mkfn!{
    render_opts_introspect!();
    # [doc = " Renders directed graph `g` into the writer `w` in DOT syntax."] # [doc = " (Main entry point for the library.)"] pub fn render_opts < 'a , N , E , G , W > (g : & 'a G , w : & mut W , options : & [RenderOption]) -> io :: Result < () > where N : Clone + 'a , E : Clone + 'a , G : Labeller < 'a , Node = N , Edge = E > + GraphWalk < 'a , Node = N , Edge = E > , W : Write , { writeln ! (w , "digraph {} {{" , g . graph_id () . as_slice ()) ? ; let mut graph_attrs = Vec :: new () ; let mut content_attrs = Vec :: new () ; let font ; if let Some (fontname) = options . iter () . find_map (| option | { if let RenderOption :: Fontname (fontname) = option { Some (fontname) } else { None } }) { font = format ! (r#"fontname="{fontname}""#) ; graph_attrs . push (& font [..]) ; content_attrs . push (& font [..]) ; } if options . contains (& RenderOption :: DarkTheme) { graph_attrs . push (r#"bgcolor="black""#) ; graph_attrs . push (r#"fontcolor="white""#) ; content_attrs . push (r#"color="white""#) ; content_attrs . push (r#"fontcolor="white""#) ; } if ! (graph_attrs . is_empty () && content_attrs . is_empty ()) { writeln ! (w , r#"    graph[{}];"# , graph_attrs . join (" ")) ? ; let content_attrs_str = content_attrs . join (" ") ; writeln ! (w , r#"    node[{content_attrs_str}];"#) ? ; writeln ! (w , r#"    edge[{content_attrs_str}];"#) ? ; } let mut text = Vec :: new () ; for n in g . nodes () . iter () { write ! (w , "    ") ? ; let id = g . node_id (n) ; let escaped = & g . node_label (n) . to_dot_string () ; write ! (text , "{}" , id . as_slice ()) . unwrap () ; if ! options . contains (& RenderOption :: NoNodeLabels) { write ! (text , "[label={escaped}]") . unwrap () ; } let style = g . node_style (n) ; if ! options . contains (& RenderOption :: NoNodeStyles) && style != Style :: None { write ! (text , "[style=\"{}\"]" , style . as_slice ()) . unwrap () ; } if let Some (s) = g . node_shape (n) { write ! (text , "[shape={}]" , & s . to_dot_string ()) . unwrap () ; } writeln ! (text , ";") . unwrap () ; w . write_all (& text) ? ; text . clear () ; } for e in g . edges () . iter () { let escaped_label = & g . edge_label (e) . to_dot_string () ; write ! (w , "    ") ? ; let source = g . source (e) ; let target = g . target (e) ; let source_id = g . node_id (& source) ; let target_id = g . node_id (& target) ; write ! (text , "{} -> {}" , source_id . as_slice () , target_id . as_slice ()) . unwrap () ; if ! options . contains (& RenderOption :: NoEdgeLabels) { write ! (text , "[label={escaped_label}]") . unwrap () ; } let style = g . edge_style (e) ; if ! options . contains (& RenderOption :: NoEdgeStyles) && style != Style :: None { write ! (text , "[style=\"{}\"]" , style . as_slice ()) . unwrap () ; } writeln ! (text , ";") . unwrap () ; w . write_all (& text) ? ; text . clear () ; } writeln ! (w , "}}") }
}
